import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:1 + n]

    edges = [False] * n
    all_dark = True

    for i in range(n):
        if p[i] + p[(i + 1) % n] < 1000:
            edges[i] = True
        else:
            all_dark = False

    if all_dark:
        print(n)
        return

    first_false = 0
    while edges[first_false]:
        first_false += 1

    start = (first_false + 1) % n
    cur = 0
    ans = 0

    for k in range(n - 1):
        idx = (start + k) % n
        if edges[idx]:
            cur += 1
            if cur > ans:
                ans = cur
        else:
            cur = 0

    print(ans)

if __name__ == "__main__":
    main()
